diff --git a/tests/web/e2e/U5/ctx-1.spec.ts b/tests/web/e2e/U5/ctx-1.spec.ts
new file mode 100644
index 00000000..743c8f3b
--- /dev/null
+++ b/tests/web/e2e/U5/ctx-1.spec.ts
@@ -0,0 +1,96 @@
+// CTX-1 · Sessions. The docs/context/ snapshot chain as a timeline across days, showing how work resumed between
+// sessions. U5's acceptance: the sessions page lists each dated snapshot oldest first, with its slug, plan · node,
+// status and next action; an undated snapshot is not guessed into it. On the `complete` trail with U5's overlay
+// (tests/web/fixtures/overlays/u5/README.md): f1-started and f1-pause-one on 2026-10-18, day-two-resumed (no plan,
+// no node) on 2026-10-19; no-front-matter has no date. Parity on the design fixture against docs/ui/derived/U5/sessions/.
+import { expect, test } from '@playwright/test';
+import { TIMELINE, allRowTexts, auditEverywhere, compileU5, heading, openOnFixture, primaryNav, region, route } from './support/app';
+import type { CompiledTrail } from './support/app';
+import { expectRegionComponents, expectRegionsInOrder, expectShell, expectTokensOnly, sessions } from './support/parity';
+
+let fixture: CompiledTrail;
+test.beforeAll(() => {
+  fixture = compileU5();
+});
+test.afterAll(() => {
+  fixture?.trail.cleanup();
+});
+
+async function openTimeline(page: import('@playwright/test').Page) {
+  await openOnFixture(page, fixture, route.sessions);
+  const timeline = region(page, TIMELINE);
+  await expect(timeline, 'the snapshot timeline is drawn').toBeVisible();
+  return timeline;
+}
+
+test("CTX-1 · the timeline lists the trail's three dated snapshots, oldest first, by slug", async ({ page }) => {
+  const timeline = await openTimeline(page);
+  await expect.poll(async () => {
+    const rows = await allRowTexts(timeline);
+    return ['f1-started', 'f1-pause-one', 'day-two-resumed'].map((slug) => rows.findIndex((r) => r.includes(slug)));
+  }).toEqual([0, 1, 2]);
+});
+
+test("CTX-1 · each session shows its plan · node, status and next action from its snapshot", async ({ page }) => {
+  const timeline = await openTimeline(page);
+  const paused = timeline.locator('table tbody tr').filter({ hasText: 'f1-pause-one' });
+  await expect(paused, 'the pause-one row').toHaveCount(1);
+  await expect(paused).toContainText('build');
+  await expect(paused).toContainText('F1');
+  await expect(paused).toContainText(/blocked/i);
+  await expect(paused).toContainText('David opens the stub routes at pause 1');
+});
+
+test('CTX-1 · the timeline spans two days: the resumed session is saved on 2026-10-19, the first on 2026-10-18', async ({ page }) => {
+  const timeline = await openTimeline(page);
+  await expect(timeline.locator('table tbody tr').filter({ hasText: 'f1-started' }).locator('time').first()).toHaveAttribute(
+    'datetime',
+    /^2026-10-18T09:00:00/,
+  );
+  await expect(timeline.locator('table tbody tr').filter({ hasText: 'day-two-resumed' }).locator('time').first()).toHaveAttribute(
+    'datetime',
+    /^2026-10-19T08:10:00/,
+  );
+});
+
+test("CTX-1 · a session with no plan or node shows the kit's empty value, never a default plan", async ({ page }) => {
+  const timeline = await openTimeline(page);
+  const resumed = timeline.locator('table tbody tr').filter({ hasText: 'day-two-resumed' });
+  await expect(resumed).toContainText("Resume F1 from pause 1 after David's ruling");
+  await expect(resumed).not.toContainText('build');
+});
+
+test('CTX-1 · the snapshot with no front matter is not guessed into the timeline', async ({ page }) => {
+  const timeline = await openTimeline(page);
+  await expect.poll(async () => (await allRowTexts(timeline)).length).toBe(3);
+  await expect(timeline).not.toContainText('no-front-matter');
+});
+
+test('CTX-1 · reachable: the sessions route answers with its own heading', async ({ page }) => {
+  await openOnFixture(page, fixture, route.sessions);
+  await expect(heading(page)).toBeVisible();
+  await expect(primaryNav(page)).toBeVisible();
+});
+
+test('CTX-1 · the sessions page has no axe violation, light and dark, at 1440 and 390', async ({ page }) => {
+  await openOnFixture(page, fixture, route.sessions);
+  await auditEverywhere(page, route.sessions, async (p) => {
+    await expect(region(p, TIMELINE).locator('table tbody tr').first()).toBeVisible();
+  });
+});
+
+test("CTX-1 · parity: the sessions page keeps its reference's regions in order", async ({ page }) => {
+  await expectRegionsInOrder(page, sessions);
+});
+
+test("CTX-1 · parity: the snapshot timeline region carries its reference's components", async ({ page }) => {
+  await expectRegionComponents(page, sessions, TIMELINE);
+});
+
+test("CTX-1 · parity: the sessions page's shell, primary nav and title are its reference's", async ({ page }) => {
+  await expectShell(page, sessions, true);
+});
+
+test('CTX-1 · parity: the sessions page uses tokens only, no literal colour', async ({ page }) => {
+  await expectTokensOnly(page, sessions);
+});
diff --git a/tests/web/e2e/U5/support/app.ts b/tests/web/e2e/U5/support/app.ts
new file mode 100644
index 00000000..7f6e8f1b
--- /dev/null
+++ b/tests/web/e2e/U5/support/app.ts
@@ -0,0 +1,53 @@
+// U5's routes (sessions, harness, stats, and the guided tour on the about page) and its fixture: the clean
+// `complete` trail (build/F1, run once) with U5's overlay laid over it (tests/web/fixtures/overlays/u5/README.md):
+// three dated context snapshots and one undated, and a generated harness file of two agents, two skills, two hooks.
+import { cpSync } from 'node:fs';
+import { join } from 'node:path';
+import type { Locator, Page } from '@playwright/test';
+import { compileFixture, repoRoot } from '../../U0b/support/trail';
+import type { CompiledTrail } from '../../U0b/support/trail';
+
+export { auditEverywhere, openOnFixture, region } from '../../U1/support/app';
+export { heading, hrefTo, primaryNav, rowTexts } from '../../U2/support/app';
+export type { CompiledTrail } from '../../U0b/support/trail';
+
+export const overlayDir = join(repoRoot, 'tests', 'web', 'fixtures', 'overlays', 'u5', 'tree');
+
+/** U5's routes (hash routing). */
+export const route = {
+  sessions: '/#/sessions',
+  harness: '/#/harness',
+  stats: '/#/stats',
+  about: '/#/about',
+  matrix: '/#/rules',
+  plan: (plan: string): string => `/#/plans/${plan}`,
+};
+
+/** The `complete` trail with U5's overlay, compiled once for a spec file. */
+export function compileU5(): CompiledTrail {
+  return compileFixture('complete', (root) => cpSync(overlayDir, root, { recursive: true }));
+}
+
+/** The regions (docs/ui/derived/U5/<screen>/screen.json). */
+export const TIMELINE = 'snapshot-timeline';
+export const AGENTS = 'agents';
+export const HOOKS = 'hooks';
+export const FACTS = 'facts-per-agent-and-node';
+export const TOUR = 'guided-tour-entry-one-rule-end-to-end-could';
+
+/** The rows of every table in `scope`, each as its text, whitespace collapsed, in page order. */
+export async function allRowTexts(scope: Locator): Promise<string[]> {
+  return scope
+    .locator('table tbody tr')
+    .evaluateAll((rows) => rows.map((tr) => (tr.textContent ?? '').replace(/\s+/g, ' ').trim()));
+}
+
+/** The row of any table in `scope` whose header cell or first cell reads `key`. */
+export function rowOf(scope: Locator, key: string | RegExp): Locator {
+  return scope.locator('table tbody tr').filter({ has: scope.page().locator('th, td').filter({ hasText: key }) });
+}
+
+/** The page's main content as text, whitespace collapsed. */
+export async function mainText(page: Page): Promise<string> {
+  return ((await page.getByRole('main').textContent()) ?? '').replace(/\s+/g, ' ').trim();
+}
diff --git a/tests/web/e2e/U5/support/parity.ts b/tests/web/e2e/U5/support/parity.ts
new file mode 100644
index 00000000..ce020c8d
--- /dev/null
+++ b/tests/web/e2e/U5/support/parity.ts
@@ -0,0 +1,107 @@
+// Parity with U5's derived reference (docs/ui/derived/U5/), the built routes served on the design fixture
+// (docs/ui/fixture/), so both sides read the same data. Structure only: the tagged regions in order, the catalogued
+// components in each, the shell, the title and the navigation, and tokens in place of literal colours. The reader is
+// U0b's (tests/web/e2e/U0b/support/reference.ts), pointed at docs/ui/derived/U5. Parity tests are the only ones,
+// with reachability, that may pass at the stub.
+//
+// A region or nav entry a later node builds (in transit against U5's own derived.json, ../../U0b/support/built.ts) is
+// compared by its place only, so these checks hold before and after it lands.
+import { expect } from '@playwright/test';
+import type { BrowserContext, Page } from '@playwright/test';
+import { serveTrace, setTheme, themes, viewports } from '../../U0b/support/app';
+import { builtAt } from '../../U0b/support/built';
+import { literalColours, readBuilt, readReference as readFromU0b, regionNamed } from '../../U0b/support/reference';
+import type { Structure } from '../../U0b/support/reference';
+import { designFixtureDir } from '../../U0b/support/trail';
+import { route } from './app';
+
+export interface Screen {
+  label: string;
+  screen: string;
+  state: string;
+  path: string;
+}
+
+// Each reference's own data in the design fixture: the sessions list, the fixture's harness block, the build plan's
+// stats, and the about page's tour.
+export const sessions: Screen = { label: 'sessions', screen: 'sessions', state: 'populated', path: route.sessions };
+export const harness: Screen = { label: 'harness', screen: 'harness', state: 'populated', path: route.harness };
+export const stats: Screen = { label: 'delivery stats', screen: 'stats', state: 'populated', path: route.stats };
+export const about: Screen = { label: 'how to read this', screen: 'about', state: 'populated', path: route.about };
+
+const { regionSettled, settledNav } = builtAt('U5');
+
+/** Reads docs/ui/derived/U5/<screen>/<state>.html: U0b's reader joins docs/ui/derived/U0b with ../U5/<screen>. */
+function readReference(context: BrowserContext, screen: string, state: string): Promise<Structure> {
+  return readFromU0b(context, `../U5/${screen}`, state);
+}
+
+async function open(page: Page, s: Screen): Promise<void> {
+  await serveTrace(page, designFixtureDir);
+  await setTheme(page, 'light');
+  await page.setViewportSize(viewports[1440]);
+  await page.goto(s.path);
+}
+
+function shellOf(s: Structure, withTitle: boolean): Record<string, unknown> {
+  return {
+    ...(withTitle ? { title: s.title } : {}),
+    shell: s.shell,
+    navLinks: settledNav(s.navLinks),
+    navNotBuilt: settledNav(s.navNotBuilt),
+    navCurrent: s.navCurrent,
+    tabCurrent: s.tabCurrent,
+  };
+}
+
+function settledOrder(s: Structure, screen: string): (string | boolean)[][] {
+  return s.regions.map((r) => (regionSettled(screen, r.slug) ? [r.slug, r.req.join(' '), r.built] : [r.slug]));
+}
+
+function unbuiltComps(s: Structure, screen: string): [string, string[]][] {
+  return s.regions.filter((r) => !r.built && regionSettled(screen, r.slug)).map((r) => [r.slug, r.comps]);
+}
+
+/** Every region of the reference, in its order, with its data-req; the unbuilt ones as the not-built-yet pattern. */
+export async function expectRegionsInOrder(page: Page, s: Screen): Promise<void> {
+  const reference = await readReference(page.context(), s.screen, s.state);
+  await open(page, s);
+  await expect
+    .poll(async () => {
+      const built = await readBuilt(page, reference);
+      return { order: settledOrder(built, s.screen), unbuilt: unbuiltComps(built, s.screen) };
+    })
+    .toEqual({ order: settledOrder(reference, s.screen), unbuilt: unbuiltComps(reference, s.screen) });
+}
+
+/** One region of the reference, with its data-req and the catalogued components inside it. */
+export async function expectRegionComponents(page: Page, s: Screen, slug: string): Promise<void> {
+  const reference = await readReference(page.context(), s.screen, s.state);
+  const wanted = regionNamed(reference, slug);
+  expect(wanted, `the reference has region ${slug}`).toBeDefined();
+  await open(page, s);
+  await expect
+    .poll(async () => {
+      const found = regionNamed(await readBuilt(page, reference), slug);
+      return found ? { req: found.req, comps: found.comps } : null;
+    })
+    .toEqual({ req: wanted?.req, comps: wanted?.comps });
+}
+
+/** The shell's components, the primary nav (links, not-built entries, the current one), the current tab, the title. */
+export async function expectShell(page: Page, s: Screen, withTitle: boolean): Promise<void> {
+  const reference = await readReference(page.context(), s.screen, s.state);
+  await open(page, s);
+  await expect.poll(async () => shellOf(await readBuilt(page, reference), withTitle)).toEqual(shellOf(reference, withTitle));
+}
+
+/** No literal colour on the page in either theme: tokens only. */
+export async function expectTokensOnly(page: Page, s: Screen): Promise<void> {
+  const reference = await readReference(page.context(), s.screen, s.state);
+  await open(page, s);
+  await expect.poll(async () => (await readBuilt(page, reference)).regions.length).toBe(reference.regions.length);
+  for (const theme of themes) {
+    await setTheme(page, theme);
+    expect.soft(await page.evaluate(literalColours), `literal colours, ${theme}`).toEqual([]);
+  }
+}
diff --git a/tests/web/fixtures/overlays/u5/README.md b/tests/web/fixtures/overlays/u5/README.md
