+  fixture?.trail.cleanup();
+});
+
+async function openTour(page: Page) {
+  await openOnFixture(page, fixture, route.about);
+  const tour = region(page, TOUR);
+  await expect(tour, 'the tour region is drawn').toBeVisible();
